     3→namespace App\Http\Controllers\Guru;
     4→
     5→use App\Http\Controllers\Controller;
     6→use App\Models\Schedule;
     7→use App\Models\Student;
     8→use App\Models\Teacher;
     9→use App\Models\SchoolClass;
    10→use App\Services\ScheduleAgreementService;
    11→use App\Services\ScheduleLockService;
    12→use Illuminate\Http\Request;
    13→use Illuminate\Support\Facades\DB;
    14→
    15→class AttendanceController extends Controller
    16→{
    17→    public function index(Request $request)
    18→    {
    19→        $user    = auth()->user();
    20→        $teacher = Teacher::where('user_id', $user->id)->first();
    21→
    22→        $schedules = Schedule::with('kelas', 'cabang')
    23→            ->when($teacher, fn($q) => $q->where('guru_id', $teacher->id))
    24→            ->when($request->tanggal, fn($q) => $q->whereDate('tanggal', $request->tanggal))
    25→            ->when(!$request->tanggal, fn($q) => $q->where('tanggal', '>=', now()->subDays(30)))
    26→            ->orderByDesc('tanggal')
    27→            ->get();
    28→
    29→        $classes = SchoolClass::when($teacher, function($q) use ($teacher) {
    30→            $q->where('cabang_id', $teacher->branch_id);
    31→        })->get();
    32→
    33→        return view('guru.attendance', compact('schedules', 'classes', 'teacher'));
    34→    }
    35→
    36→    public function getStudents(Schedule $schedule)
    37→    {
    38→        $lockService = app(ScheduleLockService::class);
    39→        $agreementService = app(ScheduleAgreementService::class);
    40→
    41→        if ($schedule->agreements()->count() === 0) {
    42→            $agreementService->syncForSchedule($schedule);
    43→        }
    44→
    45→        // Filter by branch if the schedule has a branch assigned
    46→        $students = Student::where('status', 'aktif')
    47→            ->when($schedule->cabang_id, fn($q) => $q->where('branch_id', $schedule->cabang_id))
    48→            ->orderBy('name')
    49→            ->get();
    50→
    51→        // Get existing attendance for this schedule
    52→        $existing = DB::table('absensi_siswas')
    53→            ->where('jadwal_id', $schedule->id)
    54→            ->pluck('status', 'siswa_id');
    55→
    56→        $agreements = $schedule->agreements()->get()->keyBy('student_id');
    57→
    58→        return response()->json([
    59→            'success'            => true,
    60→            'students'           => $students,
    61→            'existing'           => $existing,
    62→            'attendance_locked'  => $lockService->isAttendanceLocked($schedule),
    63→            'schedule_locked'    => $lockService->isScheduleLocked($schedule),
    64→            'all_agreed'         => $agreementService->allStudentsAgreed($schedule),
    65→            'agreements'         => $agreements,
    66→        ]);
    67→    }
    68→
    69→    public function store(Request $request)
    70→    {
    71→        $schedule = Schedule::findOrFail($request->input('jadwal_id'));
    72→        $lockService = app(ScheduleLockService::class);
    73→        $agreementService = app(ScheduleAgreementService::class);
    74→
    75→        if ($lockService->isAttendanceLocked($schedule)) {
    76→            return response()->json([
    77→                'success' => false,
    78→                'message' => 'Absensi tidak dapat diubah karena jadwal pertemuan sudah selesai.',
    79→            ], 422);
    80→        }
    81→
    82→        if (! $agreementService->allStudentsAgreed($schedule)) {
    83→            return response()->json([
    84→                'success' => false,
    85→                'message' => 'Absensi hanya dapat diisi setelah guru dan siswa sepakat pada jadwal.',
    86→            ], 422);
    87→        }
    88→
    89→        $data = $request->validate([
    90→            'jadwal_id'   => 'required|exists:schedules,id',
    91→            'absensi'     => 'required|array',
    92→            'absensi.*.siswa_id' => 'required|exists:students,id',
    93→            'absensi.*.status'   => 'required|in:hadir,izin,sakit,alpa',
    94→            'catatan'     => 'nullable|string',
    95→        ]);
    96→
    97→        foreach ($data['absensi'] as $item) {
    98→            DB::table('absensi_siswas')->updateOrInsert(
    99→                ['jadwal_id' => $data['jadwal_id'], 'siswa_id' => $item['siswa_id']],
   100→                ['status' => $item['status'], 'catatan' => $data['catatan'] ?? null, 'updated_at' => now(), 'created_at' => now()]
   101→            );
   102→        }
   103→
   104→        return response()->json(['success' => true, 'message' => 'Absensi berhasil disimpan!']);
   105→    }
   106→
   107→    public function report(Request $request)
   108→    {
   109→        $teacher = Teacher::where('user_id', auth()->id())->first();
   110→
   111→        $report = DB::table('absensi_siswas as ab')
   112→            ->join('students as s', 's.id', '=', 'ab.siswa_id')
   113→            ->join('schedules as sch', 'sch.id', '=', 'ab.jadwal_id')
   114→            ->when($teacher, fn($q) => $q->where('sch.guru_id', $teacher->id))
   115→            ->when($request->bulan, fn($q) => $q->whereMonth('sch.tanggal', $request->bulan))
   116→            ->when($request->tahun, fn($q) => $q->whereYear('sch.tanggal', $request->tahun))
   117→            ->select('s.name', DB::raw("
   118→                SUM(CASE WHEN ab.status='hadir' THEN 1 ELSE 0 END) as hadir,
   119→                SUM(CASE WHEN ab.status='izin' THEN 1 ELSE 0 END) as izin,
   120→                SUM(CASE WHEN ab.status='sakit' THEN 1 ELSE 0 END) as sakit,
   121→                SUM(CASE WHEN ab.status='alpa' THEN 1 ELSE 0 END) as alpa,
   122→                COUNT(*) as total
   123→            "))
   124→            ->groupBy('s.name', 's.id')
   125→            ->get();
   126→
   127→        return response()->json(['success' => true, 'data' => $report]);
   128→    }
   129→}
