    11→    public function syncForSchedule(Schedule $schedule): void
    12→    {
    13→        $kelas = $schedule->kelas ?? SchoolClass::find($schedule->kelas_id);
    14→        if (! $kelas) {
    15→            return;
    16→        }
    17→
    18→        $studentIds = $kelas->siswa()->pluck('students.id');
    19→
    20→        foreach ($studentIds as $studentId) {
    21→            ScheduleStudentAgreement::firstOrCreate(
    22→                ['schedule_id' => $schedule->id, 'student_id' => $studentId],
    23→                ['status' => 'pending']
    24→            );
