    28→    public function guruConfirm(Schedule $schedule, int $studentId): array
    29→    {
    30→        $agreement = ScheduleStudentAgreement::where('schedule_id', $schedule->id)
    31→            ->where('student_id', $studentId)
    32→            ->firstOrFail();
    33→
    34→        if (app(ScheduleLockService::class)->isScheduleLocked($schedule)) {
    35→            return ['success' => false, 'message' => 'Jadwal sudah terkunci (H-1 jam sebelum pertemuan).'];
    36→        }
    37→
    38→        $agreement->update(['guru_confirmed_at' => now()]);
