    50→        if (app(ScheduleLockService::class)->isScheduleLocked($schedule)) {
    51→            return ['success' => false, 'message' => 'Jadwal sudah terkunci (H-1 jam sebelum pertemuan).'];
    52→        }
    53→
    54→        $agreement->update(['siswa_confirmed_at' => now()]);
    55→        $agreement->refreshStatus();
    56→
    57→        return ['success' => true, 'message' => 'Konfirmasi jadwal berhasil.', 'agreement' => $agreement->fresh()];
    58→    }
