     3→namespace App\Services;
     4→
     5→use App\Models\Schedule;
     6→use Carbon\Carbon;
     7→
     8→class ScheduleLockService
     9→{
    10→    public function sessionStart(Schedule $schedule): Carbon
    11→    {
    12→        $date = $schedule->tanggal instanceof Carbon
    13→            ? $schedule->tanggal->format('Y-m-d')
    14→            : Carbon::parse($schedule->tanggal)->format('Y-m-d');
    15→
    16→        return Carbon::parse($date . ' ' . $schedule->jam_mulai);
    17→    }
    18→
    19→    public function sessionEnd(Schedule $schedule): Carbon
    20→    {
    21→        $date = $schedule->tanggal instanceof Carbon
    22→            ? $schedule->tanggal->format('Y-m-d')
    23→            : Carbon::parse($schedule->tanggal)->format('Y-m-d');
    24→
    25→        return Carbon::parse($date . ' ' . $schedule->jam_selesai);
    26→    }
    27→
    28→    /** Jadwal tidak bisa diubah H-1 jam sebelum mulai */
    29→    public function isScheduleLocked(Schedule $schedule): bool
    30→    {
    31→        return now()->gte($this->sessionStart($schedule)->subHour());
    32→    }
    33→
    34→    /** Absensi tidak bisa diubah setelah pertemuan selesai */
    35→    public function isAttendanceLocked(Schedule $schedule): bool
    36→    {
    37→        return now()->gt($this->sessionEnd($schedule));
    38→    }
    39→
    40→    public function canEditSchedule(Schedule $schedule): bool
    41→    {
    42→        return ! $this->isScheduleLocked($schedule) && $schedule->status !== 'selesai';
    43→    }
    44→
    45→    public function canEditAttendance(Schedule $schedule): bool
    46→    {
    47→        return ! $this->isAttendanceLocked($schedule);
    48→    }
    49→}
