    21→    public function index(Request $request)
    22→    {
    23→        $teacher = Teacher::where('user_id', auth()->id())->first();
    24→        if (! $teacher) {
    25→            return redirect()->route('guru.dashboard')->with('error', 'Profil guru belum lengkap.');
    26→        }
    27→
    28→        // Get all classes taught by this teacher
