    30→
    31→        // Get proposals for these classes
    32→        $proposals = ScheduleProposal::whereIn('class_id', $classIds)
    33→            ->with(['kelas', 'approvals'])
    34→            ->orderBy('created_at', 'desc')
    35→            ->paginate(20);
    36→
    37→        // Stats
    38→        $stats = [
    39→            'total' => $proposals->total(),
    40→            'pending' => ScheduleProposal::whereIn('class_id', $classIds)->where('status', 'pending')->count(),
    41→            'approved' => ScheduleProposal::whereIn('class_id', $classIds)->where('status', 'approved')->count(),
    42→            'rejected' => ScheduleProposal::whereIn('class_id', $classIds)->where('status', 'rejected')->count(),
