    13→    /**
    14→     * Create a new proposal and generate approval records for all class members.
    15→     */
    16→    public function propose(SchoolClass $class, string $proposerType, int $proposerId, array $data): ScheduleProposal
    17→    {
    18→        $proposal = ScheduleProposal::create([
    19→            'class_id'         => $class->id,
