    59→
    60→    private function autoApproveProposer(ScheduleProposal $proposal): void
    61→    {
    62→        ScheduleProposalApproval::where('proposal_id', $proposal->id)
    63→            ->where('approver_type', $proposal->proposed_by_type)
    64→            ->where('approver_id', $proposal->proposed_by_id)
    65→            ->update(['status' => 'approved', 'responded_at' => now()]);
    66→    }
