    68→    /**
    69→     * Record a response (approved/rejected) from a participant.
    70→     * If all approved → create schedule. If any rejected → mark rejected.
    71→     */
    72→    public function respond(ScheduleProposal $proposal, string $approverType, int $approverId, string $status): array
    73→    {
    74→        // Check lock: cannot change if meeting starts in less than 1 hour
    75→        $sessionStart = Carbon::parse($proposal->tanggal->format('Y-m-d') . ' ' . $proposal->jam_mulai);
    76→        if (now()->gte($sessionStart->subHour())) {
    77→            return ['success' => false, 'message' => 'Jadwal sudah terkunci (H-1 jam sebelum pertemuan).'];
    78→        }
    79→
    80→        if ($proposal->status !== 'pending') {
    81→            return ['success' => false, 'message' => 'Proposal ini sudah ' . $proposal->status . '.'];
    82→        }
    83→
    84→        $approval = ScheduleProposalApproval::where('proposal_id', $proposal->id)
    85→            ->where('approver_type', $approverType)
    86→            ->where('approver_id', $approverId)
    87→            ->first();
    88→
    89→        if (! $approval) {
    90→            return ['success' => false, 'message' => 'Anda tidak termasuk dalam daftar peserta proposal ini.'];
    91→        }
    92→
    93→        $approval->update(['status' => $status, 'responded_at' => now()]);
    94→
    95→        // Reload approvals
    96→        $proposal->load('approvals');
    97→
    98→        if ($status === 'rejected') {
    99→            $proposal->update(['status' => 'rejected']);
   100→            return ['success' => true, 'message' => 'Jadwal ditolak.', 'proposal_status' => 'rejected'];
   101→        }
   102→
   103→        if ($proposal->allApproved()) {
   104→            $schedule = $this->autoCreateSchedule($proposal);
   105→            $proposal->update(['status' => 'approved', 'schedule_id' => $schedule->id]);
   106→            return ['success' => true, 'message' => 'Semua pihak setuju! Jadwal otomatis dibuat.', 'proposal_status' => 'approved'];
   107→        }
   108→
   109→        return ['success' => true, 'message' => 'Persetujuan Anda telah direkam.', 'proposal_status' => 'pending'];
   110→    }
